import React from 'react';
import { useNavigate } from 'react-router-dom';

function Profile({ user, setUser }) {
  const navigate = useNavigate();

  const handleLogout = () => {
    setUser(null);
    navigate('/');
  };

  if (!user) {
    return (
      <div className="text-center mt-20">
        <h2 className="text-2xl font-bold text-gray-700">You are not logged in.</h2>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto mt-10 bg-white p-8 rounded-lg shadow-md border border-gray-100">
      <h2 className="text-3xl font-bold mb-6 text-blue-600 border-b pb-4">My Profile</h2>
      
      <div className="space-y-4 mb-8">
        <div>
          <label className="text-sm text-gray-500">Full Name</label>
          <p className="text-lg font-semibold text-gray-800">{user.name}</p>
        </div>
        <div>
          <label className="text-sm text-gray-500">Email Address</label>
          <p className="text-lg font-semibold text-gray-800">{user.email}</p>
        </div>
      </div>

      <button 
        onClick={handleLogout}
        className="bg-red-500 text-white px-6 py-2 rounded hover:bg-red-600 transition font-bold"
      >
        Sign Out
      </button>
    </div>
  );
}

export default Profile;
